@startuml

class Well {
  + code : string
  + pollutionRate() : double
}

abstract class Company {
  + taxCode : string
  + numberOfEmployees : int
}

interface OilCompany { }

class OnshoreWell {
  + surfaceExtension : double
}

class OffshoreWell {
  + yearOfInstallation : int
  + geographicalAreaCode : string
  + environmentalImportance : int
}

class Area {
  + code : string
  + environmentalImportance : int
}

Company "0..*" -- "*" Well : extractsCrudeOilFrom
OnshoreWell --|> Well
OffshoreWell --|> Well
OffshoreWell "1" -- "1" Area : locatedIn

@enduml

